select c.id as c_id, c.name as c_name, g.id as g_id, g.name as g_name from t_csys_course c left join t_csys_course_ref_graduation crg on crg.course_id = c.id left join t_csys_std_graduation g on g.id = crg.graduation_id where c.id in
#{id}
and c.type = #{type}
and c.type in (1,3)
order by g.id

select case when sum(status) > 0 then 0 else 1 end as status, scheme_id from (select trc.scheme_id, case when IFNULL(academic_terms_number, 1) = scheduleNum.s_num then 0 else 1 end as status from t_csys_course c inner join t_csys_training_scheme_ref_course trc on trc.course_id = c.id inner join (select cs.course_id, count(cs.id) as s_num from t_csys_training_scheme_course_schedule cs group by cs.course_id) scheduleNum on scheduleNum.course_id = c.id where trc.scheme_id in
#{id}
and c.semester_Schedule = '7') tab group by scheme_id
